```mql5
//+------------------------------------------------------------------+
//|                         Alert on SMA Touch                       |
//|                     Simples Média Móvel com Alerta               |
//+------------------------------------------------------------------+
#property copyright "Exemplo - Assistente"
#property version   "1.00"
#property strict
#property indicator_chart_window

input int      SMA_Period = 14;         // Período da Média Móvel
input double   Sensibilidade = 5;       // Sensibilidade em pontos (distância para alerta)
input bool     Notificacao_Ativa = true; // Enviar notificação no celular?

double EMABuffer[];                     // Buffer para a média
double PreviousAlertPrice = 0;          // Para evitar alertas repetidos

//+------------------------------------------------------------------+
//| Custom Indicator Initialization                                  |
//+------------------------------------------------------------------+
int OnInit()
  {
   // Configuração de buffers que armazenam os valores da média
   SetIndexBuffer(0, EMABuffer, INDICATOR_DATA);
   IndicatorSetString(INDICATOR_SHORTNAME, "SMA Alert (" + IntegerToString(SMA_Period) + ")");
   return(INIT_SUCCEEDED);
  }

//+------------------------------------------------------------------+
//| Custom Indicator Iteration                                       |
//+------------------------------------------------------------------+
int OnCalculate(const int rates_total,     // Total de candles no gráfico
                const int prev_calculated, // Número de candles previamente calculados
                const datetime &time[],    // Time array
                const double &open[],      // Preços de abertura
                const double &high[],      // Preços máximos
                const double &low[],       // Preços mínimos
                const double &close[],     // Preços de fechamento
                const long &tick_volume[], // Volume de ticks
                const long &volume[],      // Volume de negociação
                const int &spread[])       // Spread
  {
   // Verifica se temos dados suficientes
   if (rates_total <= SMA_Period) 
      return(0);

   // Calcula a média móvel simples
   SimpleMAOnBuffer(rates_total, prev_calculated, close, EMABuffer);

   // Checa posse de alertas
   CheckAlerts(rates_total, close);

   return(rates_total);
  }

//+------------------------------------------------------------------+
//| Calcula a Média Móvel Simples diretamente no Buffer              |
//+------------------------------------------------------------------+
void SimpleMAOnBuffer(int rates_total, int prev_calculated, const double &price[], double &buffer[])
  {
   int start = MathMax(prev_calculated - 1, SMA_Period);
   for (int i = start; i < rates_total; i++) 
     {
      double sum = 0.0;
      for (int j = 0; j < SMA_Period; j++) 
         sum += price[i - j];
      buffer[i] = sum / SMA_Period;
     }
  }

//+------------------------------------------------------------------+
//| Verifica condições para alertar                                 |
//+------------------------------------------------------------------+
void CheckAlerts(int rates_total, const double &price[])
  {
   // Obtém o preço atual e o valor da SMA no último candle
   double currentPrice = price[rates_total - 1];
   double smaValue = EMABuffer[rates_total - 1];

   // Calcula a distância entre o preço atual e a média
   double distance = MathAbs(currentPrice - smaValue);

   // Check se estamos dentro da sensibilidade definida
   if (distance <= Sensibilidade * _Point && PreviousAlertPrice != currentPrice)
     {
      // Dispara um alerta visual
      string mensagem = "O preço tocou ou chegou perto da SMA! Preço: " + DoubleToString(currentPrice, _Digits);
      Alert(mensagem);

      // Envia notificação ao celular via MetaTrader (se ativado nas configurações)
      if (Notificacao_Ativa)
         SendNotification(mensagem);

      // Atualiza o último preço alertado para evitar alertas duplicados
      PreviousAlertPrice = currentPrice;
     }
  }
```

